package com.supportsphere.controller; import com.supportsphere.service.*; import com.supportsphere.util.*; import com.supportsphere.model.*; import javafx.fxml.FXML; import javafx.scene.control.*; public class LoginController { @FXML TextField email; @FXML PasswordField password; private final AuthService auth=new AuthService(); @FXML void login(){try{User u=auth.login(email.getText(),password.getText());Session.setUser(u);switch(u.getRole()){case REQUESTER->SceneManager.show("requester-dashboard.fxml","SupportSphere — Requester");case VOLUNTEER->SceneManager.show("volunteer-dashboard.fxml","SupportSphere — Volunteer");case ADMIN->SceneManager.show("admin-dashboard.fxml","SupportSphere — Admin");}}catch(Exception e){Dialogs.error("Sign in failed",e.getMessage());}} @FXML void register(){try{SceneManager.show("register.fxml","SupportSphere — Create account");}catch(Exception e){Dialogs.error("Navigation error",e.getMessage());}} }
